+export function getAgentViewStorePaths(
+  options: StoreOptions = {},
+): AgentViewStorePaths {
+  const globalDir = options.globalDir ?? Storage.getGlobalQwenDir();
+  const daemonDir = path.join(globalDir, 'daemon');
+  return {
