+function emptyState(): AutoSkillCuratorState {
+  return { version: CURATOR_STATE_VERSION, skills: Object.create(null) };
+}
+
+function isMissing(error: unknown): boolean {
+  return (error as NodeJS.ErrnoException).code === 'ENOENT';
