+
+async function ensureRegularLockFile(lockPath: string): Promise<void> {
+  try {
+    const handle = await fs.open(lockPath, 'ax', 0o600);
+    await handle.close();
+  } catch (error) {
+    if (
+      !isMissing(error) &&
+      (error as NodeJS.ErrnoException).code !== 'EEXIST'
